template <typename T>
struct Identity {
    static const char* name = "Generic";
};

template <>
struct Identity<int> {
    static const char* name = "Integer";
};
// Use: Identity<float>::name vs Identity<int>::name

template <typename T>
struct Deleter {
    void cleanup(T& obj) { /* default cleanup */ }
};

template <typename T>
struct Deleter<T*> { // Partial specialization for pointers
    void cleanup(T* obj) { delete obj; }
};

template <typename T,
          typename = std::enable_if_t<std::is_floating_point_v<T>>>
T calculate(T val) {
    return val * 1.5;
}
// SFINAE: Only floating-point types instantiate this function.

template <typename T>
auto process(T x) ->
    std::enable_if_t<std::is_arithmetic_v<T>, T>
{
    return x + 1;
}
// SFINAE using return type: Substitution failure on non-arithmetic T.
